import XCTest
import CryptoKit
@testable import HouseBridgeCore

final class HAPCryptoTests: XCTestCase {
    /// (a, e, b, a^e mod N, a*b mod N) computed with Python's pow().
    static let vectors: [(String, String, String, String, String)] = [
        ("", "f60a097c976bf46c697d2caf82eeeacbe226e875555790f82ec1d3fcff2a3af4d46b0a18e8830e07bc1e398f1012bd4acefaecbd389be4bcfc49b64a0872e6cc3b", "", "", ""),
        ("", "8442d87208d86f40f6b239f3c7174c77a2dd02de92a49636a2fa7f0eab4c4f9b0687322e25c215a82a06ec41adea0575438b0d590bb0a844e52587be6b5c9bcf35", "", "", ""),
        ("", "84b28054aead44b0537390e50fcf31ca8e752fdf1ece615db9a6442e9e7d6b37", "", "", ""),

    ]

    func testMontgomeryMatchesReference() {
        for (a, e, b, power, product) in Self.vectors {
            XCTAssertEqual(SRP.field.pow(BigUInt(hex: a), BigUInt(hex: e)), BigUInt(hex: power))
            XCTAssertEqual(SRP.field.mul(BigUInt(hex: a), BigUInt(hex: b)), BigUInt(hex: product))
        }
    }

    func testFermatOnTheGroupPrime() {
        // a^(N-1) = 1 mod N for prime N: a corrupted constant would fail this.
        let one = BigUInt(1)
        XCTAssertEqual(SRP.field.pow(BigUInt(2), SRP.N - one), one)
        XCTAssertEqual(SRP.field.pow(SRP.g, SRP.N - one), one)
        XCTAssertEqual(SRP.N.bitWidth, 3072)
    }

    func testBigUIntBasics() {
        let a = BigUInt(hex: "ffffffffffffffffffffffff"), b = BigUInt(hex: "1")
        XCTAssertEqual((a + b).bytes(), Data([1] + [UInt8](repeating: 0, count: 12)))
        XCTAssertEqual(((a + b) - b), a)
        XCTAssertEqual((a * a).bytes(), BigUInt(hex: "fffffffffffffffffffffffe000000000000000000000001").bytes())
        XCTAssertEqual(BigUInt(bytes: Data([0, 0, 1, 2])).bytes(count: 4), Data([0, 0, 1, 2]))
    }

    func testSRPRoundTrip() throws {
        let code = "031-45-154"
        let server = SRP.Server(password: code)
        let client = SRP.Client(password: code)
        XCTAssertTrue(server.setClientPublic(client.publicKey))
        let (key, proof) = client.session(salt: server.salt, serverPublic: server.publicKey)
        let m2 = try XCTUnwrap(server.verify(clientProof: proof))
        XCTAssertEqual(key, server.sessionKey)
        XCTAssertEqual(m2, SRP.serverProof(A: client.publicKey, clientProof: proof, key: key))
    }

    func testSRPRejectsWrongCode() {
        let server = SRP.Server(password: "031-45-154")
        let client = SRP.Client(password: "031-45-155")
        XCTAssertTrue(server.setClientPublic(client.publicKey))
        let (_, proof) = client.session(salt: server.salt, serverPublic: server.publicKey)
        XCTAssertNil(server.verify(clientProof: proof))
    }

    func testSRPRejectsDegenerateClientKeys() {
        let server = SRP.Server(password: "031-45-154")
        XCTAssertFalse(server.setClientPublic(Data(repeating: 0, count: 384)))
        XCTAssertFalse(server.setClientPublic(SRP.N.bytes()))
    }

    func testTLVRoundTripWithLongValue() throws {
        let long = Data((0..<600).map { UInt8($0 % 251) })
        let encoded = TLV8.encode([(.state, Data([3])), (.publicKey, long), (.proof, Data())])
        let d = try XCTUnwrap(TLV8.dictionary(encoded))
        XCTAssertEqual(d[TLV8.Tag.state.rawValue], Data([3]))
        XCTAssertEqual(d[TLV8.Tag.publicKey.rawValue], long)
        XCTAssertEqual(d[TLV8.Tag.proof.rawValue], Data())
        XCTAssertNil(TLV8.decode(Data([1, 5, 0])))
    }
}
